  p('dpkg', 'package manager for Debian', 'dpkg ACTION [ARG]...', 'The low-level tool under apt: it installs, removes and keeps the database of .deb packages. Day to day you use it to ask questions; let apt do the installing (it fetches dependencies, dpkg doesn\'t).', [['-l [PATTERN]', 'list installed packages (ii = installed)'], ['-L PKG', 'list the files a package installed'], ['-S FILE', 'which package owns FILE'], ['-s PKG', 'status and details of a package'], ['-i FILE.deb', 'install a downloaded .deb (root)']], [['dpkg -l | grep ssh', 'installed packages about ssh'], ['dpkg -S /usr/bin/dig', 'which package owns this file'], ['dpkg -L nano', 'what nano installed']], 'apt, apt-cache', 1);
  p('dnf', 'package manager for Fedora and RHEL', 'dnf [OPTIONS] COMMAND [PACKAGE]...', 'Install, remove, search and update software on Fedora, RHEL, Rocky Linux, AlmaLinux and CentOS Stream. dnf refreshes its repository metadata by itself when it is stale, resolves dependencies, and asks before changing anything (answer y, or pass -y). Changing the system needs root. «yum» is the older name and still works.', [['install PKG', 'install packages'], ['remove PKG', 'remove packages'], ['search WORD', 'search names and summaries'], ['info PKG', 'details of a package'], ['list --installed', 'what is installed'], ['provides FILE', 'which package provides a file or command'], ['upgrade', 'update everything'], ['makecache', 'refresh the repository metadata now'], ['repolist', 'the configured repositories'], ['history', 'past transactions'], ['-y', 'answer yes to every question']], [['sudo dnf install htop', 'install something'], ['dnf search penguin', 'find something'], ['dnf provides /usr/bin/dig', 'which package has dig?'], ['sudo dnf upgrade', 'patch the whole system']], 'rpm, yum', 8);
