  p('test', 'check file types and compare values', 'test EXPRESSION\n[ EXPRESSION ]', 'Evaluate EXPRESSION and exit 0 (true) or 1 (false). [ is another name for test; the spaces inside the brackets are required.', [['-e FILE', 'FILE exists'], ['-f FILE', 'is a regular file'], ['-d FILE', 'is a directory'], ['-r/-w/-x FILE', 'is readable/writable/executable'], ['-s FILE', 'exists and is not empty'], ['-z STR / -n STR', 'string is empty / not empty'], ['A = B, A != B', 'strings equal / differ'], ['A -eq B', 'numbers equal (also -ne -lt -le -gt -ge)'], ['! EXPR', 'not'], ['EXPR -a EXPR, -o', 'and, or']], [['[ -f ~/diary.txt ] && echo found', 'one-line check'], ['if [ "$n" -gt 3 ]; then ...', 'in a script']], 'bash');
  M['['] = M.test;
  p('read', 'read a line from standard input', 'read [-p PROMPT] [-s] [-r] NAME...', 'Read one line and store it in the variable(s) NAME. A shell builtin; great for interactive scripts and "while read line" loops.', [['-p PROMPT', 'show PROMPT first'], ['-s', 'silent (for passwords)'], ['-r', 'do not treat backslashes as escapes']], [['read -p "Name? " name', 'ask a question'], ['while read line; do echo "$line"; done < file', 'process a file line by line']], 'bash');
  p('true', 'do nothing, successfully', 'true', 'Exit with status 0. Useful in loops: while true; do ...; done', [], [], 'false');
  p('false', 'do nothing, unsuccessfully', 'false', 'Exit with status 1.', [], [], 'true');
  p('tar', 'an archiving utility', 'tar -c|-x|-t [-zvf ARCHIVE] [-C DIR] [FILE]...', 'Bundle many files into one archive file, or unpack one. Remember the letters: c create, x extract, t list (table), z gzip compression, v verbose, f the archive file (comes last, right before its name), C change to DIR first.', [['-c', 'create a new archive'], ['-x', 'extract files'], ['-t', 'list the contents'], ['-z', 'filter through gzip (.tar.gz / .tgz)'], ['-v', 'list files as they are processed'], ['-f FILE', 'use archive FILE'], ['-C DIR', 'change to DIR first (e.g. extract somewhere else)']], [['tar -czvf backup.tar.gz notes/', 'create a compressed archive'], ['tar -tzf backup.tar.gz', 'peek inside'], ['tar -xzf backup.tar.gz -C ~', 'unpack into your home']], 'gzip, zip');
  p('gzip', 'compress files', 'gzip [-dkcv] FILE...', 'Compress each FILE, replacing it with FILE.gz.', [['-d', 'decompress (same as gunzip)'], ['-k', 'keep the original file'], ['-c', 'write to standard output'], ['-l', 'list compression statistics'], ['-v', 'verbose']], [['gzip big.log', 'creates big.log.gz'], ['gzip -k notes.txt', 'keep the original too']], 'gunzip, zcat, tar');
  p('gunzip', 'decompress files', 'gunzip FILE.gz...', 'Restore FILE.gz to FILE.', [['-k', 'keep the .gz file'], ['-c', 'to standard output']], [['gunzip big.log.gz', 'back to big.log']], 'gzip, zcat');
  p('zcat', 'print compressed files', 'zcat FILE.gz...', 'Print the uncompressed contents of FILE.gz without changing it.', [], [['zcat notes.txt.gz | head', 'peek inside']], 'gzip');
  p('zip', 'package and compress files', 'zip [-r] ARCHIVE.zip FILE...', 'Create a .zip archive, the format everyone else on the planet uses.', [['-r', 'include directories recursively'], ['-q', 'quiet']], [['zip -r evidence.zip logs/', 'zip a folder']], 'unzip, tar');
  p('unzip', 'list or extract files from a ZIP archive', 'unzip [-l] [-d DIR] [-o] ARCHIVE.zip', 'Extract a .zip archive.', [['-l', 'list contents only'], ['-d DIR', 'extract into DIR'], ['-o', 'overwrite without asking']], [['unzip evidence.zip', 'unpack here'], ['unzip -l evidence.zip', 'what is inside?']], 'zip');

  /* --- network --- */
  p('ip', 'show / manipulate routing, network devices, interfaces', 'ip [-br] OBJECT COMMAND', 'The modern network configuration tool.', [['ip a', 'addresses of every interface (ip addr)'], ['ip r', 'routing table (ip route)'], ['ip link', 'interfaces'], ['-br', 'brief output']], [['ip a', 'what is my IP address?'], ['ip r', 'where do packets go?']], 'ifconfig, ping', 8);
  p('ifconfig', 'configure a network interface (legacy)', 'ifconfig [INTERFACE]', 'The older way to show network interfaces. Prefer ip a.', [], [['ifconfig', 'interfaces, old style']], 'ip', 8);
  p('ping', 'send ICMP ECHO_REQUEST to network hosts', 'ping [-c COUNT] HOST', 'Check whether HOST is reachable and how long a round trip takes. Without -c it runs until you press Ctrl+C.', [['-c N', 'stop after N packets'], ['-i SECS', 'wait SECS between packets'], ['-q', 'quiet: only the summary']], [['ping -c 3 lighthouse', 'three pings'], ['ping 10.0.0.66', 'is anyone there? (Ctrl+C to stop)']], 'ip, dig, traceroute', 8);
  p('dig', 'DNS lookup utility', 'dig [+short] NAME [TYPE]\ndig -x ADDRESS', 'Ask the DNS server what a name means: usually its IP address (an A record).', [['+short', 'just the answer'], ['TYPE', 'A, AAAA, MX, TXT, NS...'], ['-x ADDR', 'reverse lookup: name for an address']], [['dig lighthouse.rootfall', 'full answer'], ['dig +short lighthouse', 'just the IP'], ['dig TXT rootfall', 'text records']], 'host, nslookup');
  p('host', 'DNS lookup utility', 'host NAME|ADDRESS', 'A short, friendly DNS lookup.', [], [['host lighthouse', 'lighthouse.rootfall has address 10.0.0.2']], 'dig, nslookup');
  p('nslookup', 'query Internet name servers', 'nslookup NAME', 'The classic DNS query tool.', [], [['nslookup lighthouse', 'look it up']], 'dig, host');
  p('ss', 'investigate sockets', 'ss [-tulpna]', 'List network sockets: what is listening for connections and what is connected. -tulpn is the classic combo: TCP, UDP, listening, processes, numeric.', [['-t', 'TCP sockets'], ['-u', 'UDP sockets'], ['-l', 'listening sockets only'], ['-p', 'show the owning process (root sees all)'], ['-n', 'numeric addresses and ports'], ['-a', 'all sockets']], [['sudo ss -tulpn', 'what is listening on this machine?'], ['ss -t', 'established TCP connections']], 'netstat, ip', 8);
  p('netstat', 'print network connections (legacy)', 'netstat [-tulpn]', 'The older tool ss replaced. Same idea, same flags.', [], [['sudo netstat -tulpn', 'listening ports, old style']], 'ss', 8);
  p('curl', 'transfer a URL', 'curl [OPTIONS] URL', 'Fetch a URL and print the response to standard output. The Swiss army knife of HTTP.', [['-o FILE', 'write to FILE instead of the screen'], ['-O', 'save using the name from the URL'], ['-I', 'fetch headers only'], ['-i', 'include headers in the output'], ['-L', 'follow redirects'], ['-s', 'silent: no progress or errors'], ['-f', 'fail silently on HTTP errors'], ['-v', 'verbose: show the conversation']], [['curl http://lighthouse/notice', 'read a page'], ['curl -o status.json http://lighthouse/status', 'save it'], ['curl -I http://lighthouse/', 'just the headers']], 'wget');
  p('wget', 'the non-interactive network downloader', 'wget [-O FILE] [-q] URL', 'Download URL into the current directory. If the file already exists, wget saves as name.1, name.2, ...', [['-O FILE', 'save as FILE'], ['-q', 'quiet']], [['wget http://lighthouse/files/hollow_activity.log', 'download a file']], 'curl');
  p('ssh', 'OpenSSH remote login client', 'ssh [-p PORT] [-i KEY] [USER@]HOST [COMMAND]', 'Log in to another machine securely and get a shell there (type exit to come back). Authentication uses your key (~/.ssh/id_ed25519) if the remote ~/.ssh/authorized_keys contains your public key; otherwise a password. The first time, you are asked to confirm the host\'s fingerprint; it is then remembered in ~/.ssh/known_hosts.', [['-p PORT', 'connect to PORT'], ['-i FILE', 'use this private key'], ['COMMAND', 'run COMMAND remotely and return']], [['ssh wren@lighthouse', 'log in to the Lighthouse'], ['ssh wren@lighthouse uptime', 'run one command remotely'], ['exit', '(on the remote) come back']], 'scp, ssh-keygen');
  p('scp', 'secure copy (remote file copy program)', 'scp [-r] SOURCE... TARGET', 'Copy files between machines over SSH. Remote paths are written USER@HOST:PATH (relative paths start in that user\'s home).', [['-r', 'copy directories recursively'], ['-P PORT', 'remote port']], [['scp wren@lighthouse:clean/lethe.conf ~/lethe.conf.clean', 'fetch a file'], ['scp notes.txt wren@lighthouse:', 'send one']], 'ssh');

  /* --- concepts --- */
  p('hier', 'description of the filesystem hierarchy', 'man hier', 'A tour of the standard Linux layout:\n/ the root of everything. /bin, /usr/bin: commands everyone uses. /sbin, /usr/sbin: system administration commands. /etc: configuration files. /home: users\' home directories. /root: root\'s home. /tmp: temporary files, cleared at reboot. /var: variable data — logs (/var/log), mail, spools, caches. /var/tmp: temporary files that survive reboots. /dev: device files (disks, terminals, /dev/null). /proc: a live view of processes and the kernel. /mnt, /media: mount points. /opt: optional add-on software. /srv: data served by this system. /boot: the kernel and bootloader. /usr/share/doc and /usr/share/man: documentation.', [], [['ls /', 'see the top level']], 'ls, cd', 7);
  p('nano', 'Nano\'s ANOther editor, inspired by Pico', 'nano [FILE]', 'A small, friendly text editor. Shortcuts are shown at the bottom (^ means Ctrl): Ctrl+O write out (save), Ctrl+X exit, Ctrl+K cut line, Ctrl+U paste, Ctrl+G help.', [], [['nano notes.txt', 'edit (or create) a file']], 'vim');
  p('vim', 'Vi IMproved, a programmer\'s text editor', 'vim [FILE]', 'A powerful modal editor. You start in NORMAL mode: press i to INSERT text, Esc to return to normal mode. Then :w saves, :q quits, :wq saves and quits, :q! quits without saving. Movement: h j k l or the arrows; x deletes a character, dd a line.', [], [['vim notes.txt', 'edit a file (Esc :q to escape)']], 'nano');
  M.vi = M.vim;
  p('sl', 'cure your bad habit of mistyping', 'sl', 'Displays a steam locomotive when you type sl instead of ls.', [], [], 'ls', 6);
  p('cowsay', 'configurable speaking cow', 'cowsay [-f tux] MESSAGE', 'Generates an ASCII cow (or penguin) saying MESSAGE.', [['-f tux', 'use a penguin instead']], [['cowsay hello', 'moo'], ['fortune | cowsay -f tux', 'penguin wisdom']], 'fortune', 6);
  p('fortune', 'print a random, hopefully interesting, adage', 'fortune', 'Prints a random saying.', [], [], 'cowsay', 6);
  p('neofetch', 'a fast, highly customizable system info script', 'neofetch', 'Show system information next to a logo. Mostly for screenshots.', [], [], 'uname');
